  output [31:0] R1_data,
  input  [17:0] W0_addr,
  input         W0_en,
                W0_clk,
  input  [31:0] W0_data,
  input  [3:0]  W0_mask,
  input  [17:0] W1_addr,
  input         W1_en,
                W1_clk,
  input  [31:0] W1_data,
  input  [3:0]  W1_mask
);

