module Counter(
  input  clock,
         reset,
         io_incEn,
         io_decEn,
  output io_empty,
         io_full
);

  reg [2:0] rCounter;
  always @(posedge clock) begin
    if (reset)
      rCounter <= 3'h0;
    else if (~(io_incEn & io_decEn)) begin
      if (io_incEn)
        rCounter <= rCounter + 3'h1;
      else if (io_decEn)
        rCounter <= rCounter - 3'h1;
    end
  end // always @(posedge)
  assign io_empty = rCounter == 3'h0;
  assign io_full = rCounter == 3'h4;
endmodule

