      else
        state <= _GEN;
      count <= state ? (_GEN_0 ? 3'h0 : count + 3'h1) : _GEN ? 3'h0 : count + 3'h1;
    end
  end // always @(posedge)
  assign chooseRd = ~state;
endmodule

